        if mode == 'obligation': selected = plan.get('tests', [])
        if mode == 'initial': selected = ['raft::tests::initial_election_2a']
        checks.test_plan = selected
        for seed in seeds or configured_seeds(tool_root):
            for family in selected:
                checks.cargo('test', seed, family)
            if mode != 'final':
                break
        if mode != 'final':
            checks.record('remaining_functional_coverage', 'OPEN', 'not_run_in_feedback', category='not_run',
                          diagnostic='Final must run every retained test family on every configured seed.')
    # Functional work cannot cross this reserved proof boundary.
    checks.phase_deadline = checks.deadline
    checks.obligation()
    if mode == 'obligation':
        return checks.finish(mode, [n for n in checks.results if n != 'remaining_functional_coverage'])
    for kind in ('foundation', 'definitions'):
        checks.verus(kind)
    for obligation in PROOF_ORDER:
        checks.verus('top', obligation=obligation)
    checks.linkage()
    checks.connections()
    # Verify all imported bodies and the actual combined caller, on this snapshot.
    checks.verus('safety')
    checks.verus('proof')
    required = [n for n in checks.results if n != 'proof']
    return checks.finish(mode, required)


def configured_seeds(root):
    return parse_seeds(settings(root).get('checks', 'seeds', fallback='1,2,3,4,5'))


def parse_seeds(text):
    seeds = list(dict.fromkeys(int(s.strip()) for s in text.split(',')))
    if not seeds or any(s < 0 or s >= 2**64 for s in seeds):
        raise ValueError('Seeds must be unsigned 64-bit integers')
    return seeds


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('kind', choices=['build', 'inventory', 'test', 'definitions', 'proof', 'top', 'foundation', 'obligation', 'feedback', 'safety', 'final'])
    parser.add_argument('selection', nargs='?', help='Test filter, proof file, or top-level obligation')
    parser.add_argument('--workspace', type=Path, default=ROOT)
    parser.add_argument('--task', choices=['full',*SCOPED_TASKS], default='full')
    parser.add_argument('--seed', type=int, default=1, help='Single-test seed; final uses --seeds or tools.ini')
    parser.add_argument('--seeds', help='Explicit complete final seed set, e.g. 1,2,3,4,5')
    parser.add_argument('--timeout', type=float, default=600, help='Wall time for this entire check invocation')
    parser.add_argument('--json', action='store_true', help='Print structured diagnostics; raw output remains in logs')
    args = parser.parse_args()
    if not math.isfinite(args.timeout) or args.timeout <= 0:
        parser.error('Timeout must be finite and positive')
    output = ROOT / 'runs/checks' / str(time.time_ns())
    if args.kind in ('final', 'safety', 'feedback', 'obligation'):
        report = evaluate(args.workspace, output=output, timeout=args.timeout,
                          seeds=parse_seeds(args.seeds) if args.seeds else None, mode=args.kind, selection=args.selection,task=args.task)
    else:
        checks = Checks(args.workspace, ROOT, ROOT, output, args.timeout, 'standalone-' + output.name,args.task)
        if args.kind in ('build', 'inventory', 'test'):
            checks.cargo(args.kind, args.seed, args.selection or '')
        else:
            if args.kind == 'top' and args.selection not in OBLIGATIONS:
                parser.error('top requires one of: ' + ', '.join(OBLIGATIONS))
            checks.verus(args.kind, entry=args.selection if args.kind == 'proof' else None,
                         obligation=args.selection if args.kind == 'top' else None)
        report = checks.finish(args.kind, list(checks.results))
    if args.json:
        print(json.dumps(report, indent=2))
    else:
        for name, result in report['checks'].items():
            print(f"{name}: {result['status']} ({result['reason']})")
            if result.get('log'):
                print('  ' + result['log'])
        print(report['status'] + ': ' + str(output / 'results.json'))
        print(SEMANTIC_BOUNDARY)
    return 0 if report['status'] in ('PASS', 'MACHINE_CHECKS_PASSED','REQUEST_VOTE_CHECKS_PASSED','ELECTION_START_CHECKS_PASSED') else 2 if report['status'] in ('BLOCKED', 'NEEDS_REVIEW') else 1


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (OSError, ValueError, KeyError) as exc:
        print(f'Check unavailable: {exc}', file=sys.stderr)
        sys.exit(2)
pub open spec fn round_valid(v: View) -> bool {
    !v.halted && v.pending.is_none() && (v.role == Role::Candidate || v.role == Role::Leader)
        && v.self_saved && v.round == Some(v.state.term)
}
// A Leader retains its election tally but does not count late equal-term votes.
pub open spec fn active(v: View) -> bool { round_valid(v) && v.role == Role::Candidate }
pub open spec fn majority(c: Config, votes: Set<u64>) -> bool {
    valid_config(c) && votes.finite()
        && (forall|n:u64| #[trigger] votes.contains(n) ==> n<c.members)
        && votes.len() > c.members / 2
}
pub open spec fn promotion_allowed(v: View, votes: Set<u64>) -> bool {
    active(v) && v.state.voted_for==Some(v.config.node)
        && votes.contains(v.config.node) && majority(v.config,votes)
}
pub open spec fn promotion_after(v: View, votes: Set<u64>) -> View {
    if promotion_allowed(v,votes) { View{role:Role::Leader,..v} } else { v }
}
pub open spec fn receive_votes(v: View, votes: Set<u64>, r: Request, out: Receive) -> Set<u64> {
    if (out is Save || out == Receive::Reject(Fault::Exhausted)) && r.term > v.state.term { Set::empty() } else { votes }
}
pub open spec fn start_votes(votes: Set<u64>, out: Campaign) -> Set<u64> {
    if out is Save { Set::empty() } else { votes }
}
pub open spec fn completion_votes(v: View, votes: Set<u64>, n: Completion) -> Set<u64> {
    if matches(v,n) {
        if !n.success { Set::empty() }
        else if v.pending.unwrap().action is Send { Set::<u64>::empty().insert(v.config.node) }
        else { votes }
    } else { votes }
}
pub open spec fn valid_context(v: View, c: RpcContext) -> bool {
    c.sent.config == v.config && c.peer < v.config.members && c.peer != v.config.node
        && c.sent.request.candidate == v.config.node && valid_request(v.config,c.sent.request)
}
pub open spec fn higher(v: View, c: RpcContext, r: RpcResult) -> bool {
    !v.halted && v.pending.is_none() && valid_context(v,c)
        && r is Reply && r->Reply_term > v.state.term
}
pub open spec fn collect_result(v: View, votes: Set<u64>, c: RpcContext, r: RpcResult) -> Collect {
    if v.halted { Collect::Reject(Fault::Halted) }
    else if v.pending.is_some() { Collect::Reject(Fault::Busy) }
    else if !valid_context(v,c) { Collect::Reject(Fault::Invalid) }
    else { match r {
        RpcResult::Error => Collect::Ignored,
        RpcResult::Reply{term,granted} => {
            if term > v.state.term {
                if v.next == u64::MAX { Collect::Reject(Fault::Exhausted) }
                else { Collect::Save(Write{record:Record{op:v.next,state:Persistent{
                    term,voted_for:None,log:v.state.log}},request:None,action:Action::Persisted}) }
            } else if active(v) && granted && term == v.state.term && c.sent.request.term == term
                && c.sent.request.log == v.state.log && !votes.contains(c.peer) { Collect::Counted }
            else { Collect::Ignored }
        }
    } }
}
pub open spec fn collect_after(v: View, c: RpcContext, r: RpcResult, out: Collect) -> View {
    if higher(v,c,r) {
        View{state:Persistent{term:r->Reply_term,voted_for:None,log:v.state.log},role:Role::Follower,
            next:if v.next < u64::MAX { (v.next + 1) as u64 } else { v.next },
            pending:match out { Collect::Save(w) => Some(w), _ => None },
            halted:v.next == u64::MAX,round:None,self_saved:false,..v}
    } else { v }
}
pub open spec fn collect_votes(v: View, votes: Set<u64>, c: RpcContext, r: RpcResult, out: Collect) -> Set<u64> {
    if higher(v,c,r) { Set::empty() }
    else if out == Collect::Counted { votes.insert(c.peer) } else { votes }
}
// Nonvacuity and a specification sanity check; neither proves an implementation.
pub proof fn rules_are_nonempty()
    ensures grants(fresh_view(Config{node:0,members:3}, Initial{
        state:Persistent{term:2,voted_for:None,log:Log{term:1,index:4}},role:Role::Follower}),
        Request{term:2,candidate:1,log:Log{term:1,index:4}}),
{ }
}
